//
// Scripts
//

window.addEventListener('DOMContentLoaded', function (event) {
  // Toggle the side navigation
  var sidebarToggle = document.body.querySelector('#sidebarToggle');
  if (sidebarToggle) {
    // Uncomment Below to persist sidebar toggle between refreshes
    // if (localStorage.getItem('sb|sidebar-toggle') === 'true') {
    //     document.body.classList.toggle('tta-sidenav-toggled');
    // }
    sidebarToggle.addEventListener('click', function (event) {
      event.preventDefault();
      document.body.classList.toggle('tta-sidenav-toggled');
      localStorage.setItem('sb|sidebar-toggle', document.body.classList.contains('tta-sidenav-toggled'));
      if (window.innerWidth < 991 && document.body.classList.contains('tta-sidenav-toggled')) {
        document.getElementById('ttaLayoutSidenav_content').style.marginLeft = '0';
      } else if (window.innerWidth > 991 && document.body.classList.contains('tta-sidenav-toggled')) {
        document.getElementById('ttaLayoutSidenav_content').style.marginLeft = '-170px';
      } else {
        if (window.innerWidth > 550 && window.innerWidth < 991) {
          document.getElementById('ttaLayoutSidenav_content').style.marginLeft = '-150px';
        } else if (window.innerWidth < 576) {
          document.getElementById('ttaLayoutSidenav_content').style.marginLeft = '-150px';
        } else if (window.innerWidth > 991) {
          document.getElementById('ttaLayoutSidenav_content').style.marginLeft = '0px';
        }
      }
    });
  }
});
window.onresize = function () {
  if (document.getElementById('ttaLayoutSidenav_content')) {
    if (window.innerWidth > 991) {
      document.getElementById('ttaLayoutSidenav_content').style.marginLeft = '0';
    } else if (window.innerWidth > 767 && window.innerWidth < 991) {
      document.getElementById('ttaLayoutSidenav_content').style.marginLeft = '-160px';
    } else if (window.innerWidth > 576 && window.innerWidth < 768) {
      document.getElementById('ttaLayoutSidenav_content').style.marginLeft = '-170px';
    } else if (window.innerWidth < 576) {
      document.getElementById('ttaLayoutSidenav_content').style.marginLeft = '-150px';
    }
  }
};

